#!/usr/bin/env python3
# Some portions generated by Codex. Isolate common application dependencies from the measured LMDB delta.
import pathlib,zipfile,shutil,hashlib,json
root=pathlib.Path(__file__).resolve().parents[3];d=pathlib.Path(__file__).resolve().parent
boot=root/'tools/server-boot/target/rdf4j-server-boot-6.2.0-SNAPSHOT.jar';runtime=d/'runtime'
assert not runtime.exists(),'Refuse replacing frozen runtime'
shutil.copy2(boot,d/'boot-frozen.jar')
with zipfile.ZipFile(boot) as z:
 for n in z.namelist():
  if n.startswith(('BOOT-INF/classes/','BOOT-INF/lib/')):z.extract(n,runtime)
libs=list(sorted((runtime/'BOOT-INF/lib').glob('*.jar')));byname={p.name:p for p in libs};inc=d/'incumbent-dependencies';inc.mkdir()
overrides=[]
# Same dependency bytes as the incumbent embedded experiment, when they are also Boot application dependencies.
for part in (root/'experiments/threadlocal-audit/record-cancellation/cp-a.txt').read_text().strip().split(':'):
 p=pathlib.Path(part)
 if p.is_file() and p.name in byname and p.name.startswith('rdf4j-'):
  if p.name.startswith('rdf4j-sail-lmdb-'):continue
  dest=inc/p.name;shutil.copy2(p,dest);overrides.append(dest);libs.remove(byname[p.name])
libs=[p for p in libs if not p.name.startswith('rdf4j-sail-lmdb-')]
# Keep a complete binary module and replace only the pinned writer source later via javac.
binary=next(p for p in [*overrides,*libs] if p.name.startswith('rdf4j-queryresultio-binary-'))
writer=d/'writer-on';writer.mkdir()
with zipfile.ZipFile(binary) as z:z.extractall(writer)
libs=[p for p in libs if p!=binary];overrides=[p for p in overrides if p!=binary]
base=root/'experiments/threadlocal-audit/record-cancellation/baseline-classes';depth=root/'experiments/threadlocal-audit/read-depth/layer'
common=[d/'harness',writer,base,*overrides,runtime/'BOOT-INF/classes',*libs]
(d/'cp-base.txt').write_text(':'.join(map(str,common))+'\n');(d/'cp-depth.txt').write_text(':'.join(map(str,[depth,*common]))+'\n')
manifest={'bootSha256':hashlib.sha256(boot.read_bytes()).hexdigest(),'sourceBase':'5ac89b5c137030fea1aa6aa7160984423d7f4cd5','sourceDepth':'0750336e71ab0ca0d216ce9c36483a6e9063337d','commonJars':{str(p.relative_to(d)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [*overrides,*libs]},'binaryDonor':str(binary),'note':'Reconstructed common server stack; pinned writer compiled separately; resource/cancellation/memo observer excluded.'}
(d/'application-manifest.json').write_text(json.dumps(manifest,indent=2))
